import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class FixedFileAccess {
    public static void main(String[] args) {
        String fileName = "example.txt";

        // Define the base directory securely
        String baseDir = "/var/www/html/";

        // Construct the full path using Paths to handle normalization
        Path basePath = Paths.get(baseDir).toAbsolutePath().normalize();
        Path requestedPath = Paths.get(baseDir + fileName).toAbsolutePath().normalize();

        // CRITICAL FIX: Ensure the resolved path is strictly within the base directory
        // Prevents path traversal attacks like "../etc/passwd"
        if (requestedPath.startsWith(basePath)) {
            File file = requestedPath.toFile();
            if (file.exists()) {
                System.out.println("File found: " + file.getAbsolutePath());
            } else {
                System.out.println("File not found.");
            }
        } else {
            System.out.println("Access denied: Invalid path.");
        }
    }
}
